<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { genTypeApi, taskApi } from '@/api/modules'
import { connectWs, onWsEvent } from '@/ws/client'
import GlassCard from '@/v2/components/GlassCard.vue'
import MediaViewer from '@/v2/components/MediaViewer.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import V2Field from '@/v2/components/V2Field.vue'
import TaskDetailDrawer from './TaskDetailDrawer.vue'
import { useTaskOutputThumbs } from './useTaskOutputThumbs'
import './task-output-thumbnails.css'
import { activeStatuses, flattenGenerationMenu, formatDate, statusMeta, todayRange, type GenerationTypeItem, type TaskItem, type TaskOutput } from './model'
const route=useRoute();const router=useRouter();const tasks=ref<TaskItem[]>([]);const types=ref<GenerationTypeItem[]>([]);const outputs=ref<Record<number,TaskOutput[]>>({});const loading=ref(false);const actionId=ref<number|null>(null);const bulkLoading=ref(false);const selected=ref(new Set<number>());const keyword=ref('');const status=ref('');const typeId=ref('');const date=ref(todayRange().date);const detail=ref<TaskItem|null>(null);const preview=ref<TaskOutput|null>(null);let off:(()=>void)|null=null;let timer:ReturnType<typeof setTimeout>|null=null
const names=computed(()=>Object.fromEntries(types.value.map(v=>[v.id,v.name])));const filtered=computed(()=>{const q=keyword.value.trim().toLowerCase();return tasks.value.filter(t=>!q||[t.id,t.batch_id,t.params?.prompt,t.error].some(v=>String(v||'').toLowerCase().includes(q)))});const allSelected=computed(()=>filtered.value.length>0&&filtered.value.every(task=>selected.value.has(task.id)))
const {withThumbs,release}=useTaskOutputThumbs()
async function load(){loading.value=true;try{const params:any={};if(status.value)params.status=status.value;if(typeId.value)params.generation_type_id=Number(typeId.value);if(date.value){const from=new Date(`${date.value}T00:00:00`);const to=new Date(from);to.setDate(to.getDate()+1);params.created_from=from.toISOString();params.created_to=to.toISOString()}tasks.value=await taskApi.list(params);void loadPreviews(tasks.value)}finally{loading.value=false}}
async function loadPreviews(items:TaskItem[]){const queue=items.filter(t=>t.status==='SUCCESS'&&!(outputs.value[t.id]?.length));let cursor=0;async function worker(){while(cursor<queue.length){const task=queue[cursor++];try{const list=await taskApi.outputs(task.id);release(outputs.value[task.id]);outputs.value[task.id]=await withThumbs(list)}catch{delete outputs.value[task.id]}}}await Promise.all(Array.from({length:Math.min(5,queue.length)},worker))}
async function act(task:TaskItem,action:'cancel'|'retry'|'regenerate'|'delete'){actionId.value=task.id;try{if(action==='delete'){if(!confirm(`确定删除任务 #${task.id}？生成产物会保留在素材库。`))return;await taskApi.delete(task.id)}else await taskApi[action](task.id);selected.value.delete(task.id);await load()}catch(e:any){alert(e.response?.data?.detail||'操作失败')}finally{actionId.value=null}}
function toggle(taskId:number){const next=new Set(selected.value);next.has(taskId)?next.delete(taskId):next.add(taskId);selected.value=next}function toggleAll(){selected.value=allSelected.value?new Set():new Set(filtered.value.map(task=>task.id))}
async function bulk(action:'delete'|'cancel'|'retry'|'regenerate'){const ids=[...selected.value];if(!ids.length)return;const label={delete:'删除',cancel:'取消',retry:'重试',regenerate:'重新生成'}[action];if(!confirm(`对已选择的 ${ids.length} 个任务执行“${label}”？${action==='delete'?'生成产物会保留在素材库。':''}`))return;bulkLoading.value=true;try{const result=await taskApi.bulk(ids,action);selected.value=new Set();await load();alert(`批量${label}完成：成功 ${result.succeeded}，失败 ${result.failed.length}${result.failed.length?'\n'+result.failed.map((v:any)=>`#${v.task_id} ${v.reason}`).join('\n'):''}`)}catch(e:any){alert(e.response?.data?.detail||'批量操作失败')}finally{bulkLoading.value=false}}
function reset(){keyword.value='';status.value='';typeId.value='';date.value=todayRange().date;void load()} function schedule(){if(timer)clearTimeout(timer);timer=setTimeout(()=>void load(),400)}
onMounted(async()=>{types.value=flattenGenerationMenu(await genTypeApi.menu());await load();const requested=Number(route.query.task);if(requested){const found=tasks.value.find(t=>t.id===requested);detail.value=found||await taskApi.get(requested)}connectWs();off=onWsEvent(schedule)});onUnmounted(()=>{off?.();if(timer)clearTimeout(timer)})
</script>
<template><div class="v2-page"><div class="v2-page-heading heading"><div><StatusBadge tone="info">真实任务数据</StatusBadge><h1>任务管理</h1><p>默认显示当天任务，共 {{ filtered.length }} 项</p></div><V2Button :disabled="loading" @click="load">{{ loading?'刷新中…':'刷新' }}</V2Button></div><GlassCard padding="sm"><div class="filters"><V2Field label="关键词"><input v-model="keyword" placeholder="任务 ID、批次、提示词或错误"/></V2Field><V2Field label="状态"><select v-model="status" @change="load"><option value="">全部状态</option><option v-for="(meta,key) in statusMeta" :key="key" :value="key">{{ meta.label }}</option></select></V2Field><V2Field label="生成类型"><select v-model="typeId" @change="load"><option value="">全部类型</option><option v-for="type in types" :key="type.id" :value="type.id">{{ type.name }}</option></select></V2Field><V2Field label="创建日期"><input v-model="date" type="date" @change="load"/></V2Field><V2Button variant="ghost" @click="reset">重置</V2Button></div></GlassCard><div class="bulk-bar" :class="{active:selected.size}"><label><input type="checkbox" :checked="allSelected" @change="toggleAll"/> 全选当前结果</label><span>已选择 {{ selected.size }} 项</span><div><V2Button variant="ghost" :disabled="!selected.size||bulkLoading" @click="bulk('cancel')">批量取消</V2Button><V2Button variant="ghost" :disabled="!selected.size||bulkLoading" @click="bulk('retry')">批量重试</V2Button><V2Button variant="ghost" :disabled="!selected.size||bulkLoading" @click="bulk('regenerate')">批量重新生成</V2Button><V2Button variant="danger" :disabled="!selected.size||bulkLoading" @click="bulk('delete')">批量删除</V2Button></div></div>
<div class="task-table"><div class="table-head"><span>选择</span><span>任务</span><span>状态</span><span>生成类型 / 提示词</span><span>预览</span><span>创建时间</span><span>操作</span></div><article v-for="task in filtered" :key="task.id" class="task-row" :class="{selected:selected.has(task.id)}"><label class="row-check"><input type="checkbox" :checked="selected.has(task.id)" @change="toggle(task.id)"/><span>选择任务 #{{ task.id }}</span></label><b>#{{ task.id }}<small>批次 {{ task.batch_id }} · 行 {{ task.row_no }}</small></b><StatusBadge :tone="statusMeta[task.status]?.tone">{{ statusMeta[task.status]?.label||task.status }}</StatusBadge><div class="type-prompt"><b>{{ names[task.generation_type_id||0]||'未分类' }}</b><span>{{ task.params?.prompt||task.error||'无提示词' }}</span></div><div class="previews"><button v-for="out in (outputs[task.id]||[]).slice(0,3)" :key="out.id" @click="preview=out"><img v-if="out.media_type!=='audio'" :src="out.thumbUrl"/><span v-else>♪</span><i v-if="out.media_type==='video'">▶</i></button><small v-if="!(outputs[task.id]||[]).length">—</small></div><time>{{ formatDate(task.created_at) }}</time><div class="actions"><button @click="detail=task;router.replace({query:{...route.query,task:task.id}})">详情</button><button v-if="activeStatuses.includes(task.status)" @click="act(task,'cancel')">取消</button><button v-if="['FAILED','CANCELLED'].includes(task.status)" @click="act(task,'retry')">重试</button><button v-if="['SUCCESS','FAILED'].includes(task.status)" @click="act(task,'regenerate')">重新生成</button><button v-if="!activeStatuses.includes(task.status)" class="danger" @click="act(task,'delete')">删除</button></div></article><div v-if="!filtered.length&&!loading" class="empty">当前条件下没有任务</div></div>
<TaskDetailDrawer :open="!!detail" :task="detail" @close="detail=null;router.replace({query:{}})" @changed="load"/><MediaViewer :open="!!preview" :output="preview" @close="preview=null"/></div></template>
<style scoped>.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:16px}.heading h1{margin-top:14px}.filters{display:grid;grid-template-columns:2fr 1fr 1.2fr 1fr auto;align-items:end;gap:10px}.bulk-bar{margin-top:14px;padding:10px 14px;display:flex;align-items:center;gap:16px;background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:12px;color:var(--v2-text-muted)}.bulk-bar.active{border-color:rgba(130,149,255,.45);background:rgba(130,149,255,.09)}.bulk-bar label{display:flex;align-items:center;gap:7px}.bulk-bar>div{margin-left:auto;display:flex;gap:7px;flex-wrap:wrap}.task-table{margin-top:12px;overflow:hidden;background:var(--v2-surface);border:1px solid var(--v2-border);border-radius:var(--v2-radius-lg);box-shadow:var(--v2-shadow-soft);backdrop-filter:blur(var(--v2-blur))}.table-head,.task-row{display:grid;grid-template-columns:42px 78px 90px minmax(180px,1fr) 158px 152px 220px;gap:10px;align-items:center}.table-head{min-height:44px;padding:0 14px;color:var(--v2-text-subtle);font-size:11px;border-bottom:1px solid var(--v2-border)}.task-row{min-height:86px;padding:10px 14px;border-bottom:1px solid var(--v2-border)}.task-row.selected{background:rgba(130,149,255,.06)}.row-check{display:grid;place-items:center}.row-check span{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.row-check input{width:17px;height:17px}.task-row> b{display:grid;gap:5px}.task-row> b small,.type-prompt span,time{color:var(--v2-text-muted);font-size:11px}.type-prompt{min-width:0;display:grid;gap:5px}.type-prompt span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.previews{display:flex;gap:5px}.previews button{width:48px;height:48px;padding:0;position:relative;display:grid;place-items:center;color:var(--v2-text);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:8px;overflow:hidden;cursor:pointer}.previews img{width:100%;height:100%;object-fit:contain}.previews i{position:absolute;font-style:normal;text-shadow:0 1px 3px #000}.actions{display:flex;flex-wrap:wrap;gap:5px}.actions button{padding:5px 8px;color:var(--v2-text-muted);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:7px;cursor:pointer}.actions .danger{color:var(--v2-danger)}.empty{padding:70px;text-align:center;color:var(--v2-text-muted)}@media(max-width:1100px){.filters{grid-template-columns:2fr 1fr 1fr}.filters>*:nth-child(4),.filters>*:nth-child(5){grid-column:auto}.table-head{display:none}.task-row{margin:10px;grid-template-columns:34px 75px 90px 1fr 150px;border:1px solid var(--v2-border);border-radius:14px}.task-row time{display:none}.actions{grid-column:4/6}.previews{grid-row:1/3;grid-column:5}}@media(max-width:700px){.filters{grid-template-columns:1fr 1fr}.filters>*:first-child{grid-column:span 2}.bulk-bar{align-items:flex-start;flex-wrap:wrap}.bulk-bar>div{width:100%;margin-left:0}.bulk-bar>div>*{flex:1}.task-table{background:transparent;border:0;box-shadow:none}.task-row{padding:14px;grid-template-columns:34px 1fr auto}.row-check{grid-column:1}.task-row> b{grid-column:2}.task-row>.badge{grid-column:3}.type-prompt,.previews,.actions{grid-column:1/4}.previews{grid-row:auto}.previews button{width:64px;height:64px}}</style>
